  // engine/src/extractor/normalize.ts
  var NIQUD = /[\u0591-\u05BD\u05BF-\u05C7]/g;
  var TATWEEL = /ـ/g;
  var CANTILLATION_OTHERS = /[\u05C1-\u05C7]/g;
  var QUOTE_MAP = {
    "\u201C": '"',
    "\u201D": '"',
    "\u201E": '"',
    "\u05F3": "'",
    "\u2019": "'",
    "\u05F4": '"',
    "\u2018": "'",
    "\u05BE": "-"
    // Hebrew maqaf -> plain hyphen for matching stability
  };
  var ZERO_WIDTH = /[\u200B-\u200F\u202A-\u202E\uFEFF]/g;
  var MULTISPACE = /[ \t\f\v]+/g;
  function normalizeHebrewText(input) {
    let s = (input ?? "").normalize("NFC");
    s = s.replace(ZERO_WIDTH, "");
    s = s.replace(TATWEEL, "").replace(NIQUD, "").replace(CANTILLATION_OTHERS, "");
    s = [...s].map((ch) => QUOTE_MAP[ch] ?? ch).join("");
    s = s.split("\n").map((line) => line.replace(MULTISPACE, " ").trim()).join("\n");
    return s.trim();
  }

