      all(all(SPEECH, yes("message.reports_religious_noncompliance"), yes("matter.is_between_man_and_god")), yes("matter.single_private_lapse")),
      yes("evidence.multiple_firsthand_witnesses"),
      "\u05E8\u05D0\u05D9\u05D9\u05EA \u05E9\u05E0\u05D9\u05D9\u05DD \u05E9\u05DC \u05D0\u05D9\u05E8\u05D5\u05E2 \u05D0\u05D7\u05D3 \u05D0\u05D9\u05E0\u05D4 \u05D4\u05D9\u05E1\u05D8\u05D5\u05E8\u05D9\u05D4 \u05E9\u05DC \u05D7\u05D8\u05D0\u05D9\u05DD \u05D5\u05D0\u05D9\u05E0\u05D4 \u05DE\u05D5\u05E6\u05D9\u05D0\u05D4 \u05D0\u05D3\u05DD \u05DE\u05E2\u05DE\u05D9\u05EA\u05DA; \u05D2\u05D1\u05D5\u05DC\u05D5\u05EA \u05D4\u05D2\u05D9\u05DC\u05D5\u05D9 \u05DC\u05D2\u05D5\u05E8\u05DD \u05DE\u05D5\u05E1\u05DE\u05DA \u05E0\u05D1\u05D3\u05DC\u05D9\u05DD \u05DE\u05E4\u05E8\u05E1\u05D5\u05DD \u05DC\u05D0\u05D7\u05E8\u05D9\u05DD"
