      all(IDENTIFIED, yes("context.inquiry_has_future_purpose")),
      yes("context.inquiry_includes_unrelated_people"),
      "\u05E9\u05D0\u05DC\u05D5\u05EA \u05E2\u05DC \u05D0\u05E0\u05E9\u05D9\u05DD \u05E9\u05D0\u05D9\u05DF \u05DC\u05D2\u05D1\u05D9\u05D4\u05DD \u05EA\u05D5\u05E2\u05DC\u05EA \u05D0\u05D9\u05E0\u05DF \u05DE\u05E7\u05D1\u05DC\u05D5\u05EA \u05D0\u05EA \u05DE\u05D8\u05E8\u05EA \u05D4\u05D1\u05D9\u05E8\u05D5\u05E8 \u05D4\u05DE\u05E8\u05DB\u05D6\u05D9; \u05D0\u05D9\u05DF \u05DC\u05D4\u05E1\u05D5\u05D5\u05EA \u05D0\u05EA \u05E0\u05D5\u05E9\u05D0 \u05D4\u05D4\u05EA\u05E7\u05E9\u05E8\u05D5\u05EA \u05D1\u05D0\u05DE\u05E6\u05E2\u05D5\u05EA \u05D2\u05E0\u05D5\u05EA \u05D0\u05D7\u05E8\u05D9\u05DD"
