      SPEECH,
      yes("audience.is_close_to_speaker_or_subject"),
      "\u05DE\u05E1\u05D9\u05E8\u05D4 \u05DC\u05D1\u05DF \u05D6\u05D5\u05D2 \u05D0\u05D5 \u05E9\u05D5\u05EA\u05E3 \u05D3\u05D5\u05E8\u05E9\u05EA \u05EA\u05D5\u05E2\u05DC\u05EA \u05E2\u05EA\u05D9\u05D3\u05D9\u05EA \u05D5\u05EA\u05E0\u05D0\u05D9\u05DD; \u05E9\u05DE\u05D5\u05E2\u05D4 \u05DC\u05D4\u05D2\u05E0\u05D4 \u05E6\u05E8\u05D9\u05DB\u05D4 \u05DC\u05D4\u05D9\u05DE\u05E1\u05E8 \u05DB\u05E9\u05DE\u05D5\u05E2\u05D4"
